  val trayX=playRight+size.width*.006f;val trayW=size.width-playRight-size.width*.012f;val trayH=size.height*.40f
  drawRoundRect(Brush.horizontalGradient(listOf(p.frameDark.copy(.54f),p.frame.copy(.68f),p.frameDark.copy(.54f))),Offset(trayX,rail*2.2f),Size(trayW,trayH),CornerRadius(10f));drawRoundRect(p.frameDark.copy(.28f),Offset(trayX,rail*2.2f),Size(trayW,trayH),CornerRadius(10f),style=Stroke(3.5f));drawRoundRect(Color.White.copy(.18f),Offset(trayX+4f,rail*2.2f+4f),Size(trayW-8f,trayH-8f),CornerRadius(8f),style=Stroke(2f));drawRoundRect(Brush.horizontalGradient(listOf(p.frameDark.copy(.54f),p.frame.copy(.68f),p.frameDark.copy(.54f))),Offset(trayX,size.height-rail*2.2f-trayH),Size(trayW,trayH),CornerRadius(10f));drawRoundRect(p.frameDark.copy(.28f),Offset(trayX,size.height-rail*2.2f-trayH),Size(trayW,trayH),CornerRadius(10f),style=Stroke(3.5f));drawRoundRect(Color.White.copy(.18f),Offset(trayX+4f,size.height-rail*2.2f-trayH+4f),Size(trayW-8f,trayH-8f),CornerRadius(8f),style=Stroke(2f))
  fun DrawScope.carvedSlot(y:Float){val sx=trayX+trayW*.16f;val sw=trayW*.68f;val sh=(trayH-16f)/15f*.62f;drawRoundRect(Color.Black.copy(.42f),Offset(sx-1.5f,y-1.5f),Size(sw+3f,sh+3f),CornerRadius(sh/2));drawRoundRect(Brush.verticalGradient(listOf(p.frameDark.copy(.58f),p.frame.copy(.34f))),Offset(sx,y),Size(sw,sh),CornerRadius(sh/2));drawLine(Color.White.copy(.23f),Offset(sx+sh*.35f,y+sh-1f),Offset(sx+sw-sh*.35f,y+sh-1f),1f)};val slotStep=(trayH-16f)/15f;for(i in 0..14){carvedSlot(rail*2.2f+8f+i*slotStep);carvedSlot(size.height-rail*2.2f-trayH+8f+i*slotStep)}
  val trayMark=Path().apply{moveTo(trayX+trayW/2,size.height*.47f);lineTo(trayX+trayW*.72f,size.height/2);lineTo(trayX+trayW/2,size.height*.53f);lineTo(trayX+trayW*.28f,size.height/2);close()};drawPath(trayMark,p.accent.copy(.52f));drawPath(trayMark,Color.White.copy(.24f),style=Stroke(1.5f));drawLine(Color.White.copy(.18f),Offset(trayX+trayW*.18f,rail*2.2f+8f),Offset(trayX+trayW*.18f,rail*2.2f+trayH-8f),1.5f);drawLine(Color.White.copy(.18f),Offset(trayX+trayW*.18f,size.height-rail*2.2f-trayH+8f),Offset(trayX+trayW*.18f,size.height-rail*2.2f-8f),1.5f)
  drawLine(Color.Black.copy(.48f),Offset(playLeft,rail),Offset(playRight,rail),8f);drawLine(Color.White.copy(.18f),Offset(playLeft,rail+5f),Offset(playRight,rail+5f),2f);drawLine(Color.Black.copy(.42f),Offset(playLeft,size.height-rail),Offset(playRight,size.height-rail),8f);drawLine(Color.White.copy(.12f),Offset(playLeft,size.height-rail-5f),Offset(playRight,size.height-rail-5f),2f);drawLine(Color.Black.copy(.40f),Offset(playLeft,rail),Offset(playLeft,size.height-rail),7f);drawLine(Color.White.copy(.14f),Offset(playLeft+5f,rail),Offset(playLeft+5f,size.height-rail),2f)
  drawLine(Color.White.copy(.28f),Offset(barLeft+3f,rail),Offset(barLeft+3f,size.height-rail),3f);drawLine(Color.Black.copy(.62f),Offset(barLeft+barW-3f,rail),Offset(barLeft+barW-3f,size.height-rail),6f);drawRoundRect(p.accent.copy(.46f),Offset(barLeft+6f,rail+6f),Size(barW-14f,size.height-rail*2-12f),CornerRadius(7f),style=Stroke(2f));drawLine(Color.Black.copy(.24f),Offset(barLeft+barW*.50f,rail+9f),Offset(barLeft+barW*.50f,size.height-rail-9f),1.5f)
  for(c in 0..11){val x=if(c<6)playLeft+c*cw else barLeft+barW+(c-6)*cw;val color=if(c%2==0)p.pointA else p.pointB;val other=if(c%2==0)p.pointB else p.pointA;val top=Path().apply{moveTo(x+cw*.10f,rail);lineTo(x+cw*.90f,rail);lineTo(x+cw/2,size.height*.405f);close()};val bottom=Path().apply{moveTo(x+cw*.10f,size.height-rail);lineTo(x+cw*.90f,size.height-rail);lineTo(x+cw/2,size.height*.595f);close()};drawPath(top,Brush.verticalGradient(listOf(color.copy(.72f),color,color.copy(.76f)),rail,size.height*.43f));drawPath(bottom,Brush.verticalGradient(listOf(other.copy(.76f),other,other.copy(.72f)),size.height*.57f,size.height-rail));drawPath(top,Color.Black.copy(.20f),style=Stroke(1.5f));drawPath(bottom,Color.Black.copy(.20f),style=Stroke(1.5f))}
  fun center(point:Int,index:Int):Offset{val col=if(point<12)11-point else point-12;val x=if(col<6)playLeft+(col+.5f)*cw else barLeft+barW+(col-5.5f)*cw;val r=cw*.262f;val gap=min(r*1.72f,(size.height*.37f)/5);return Offset(x,if(point>=12)rail+r+index.coerceAtMost(4)*gap else size.height-rail-r-index.coerceAtMost(4)*gap)}
  fun DrawScope.piece(c:Offset,r:Float,white:Boolean,on:Boolean=false,available:Boolean=false){
   val base=when(theme){BoardTheme.PREMIUM_WOOD->if(white)Color(0xffe2c58d)else Color(0xff603326);BoardTheme.MARBLE_STONE->if(white)Color(0xffe8e8e2)else Color(0xff34434d);BoardTheme.SMOKED_GLASS->if(white)Color(0xffb5edf0)else Color(0xff123b52)}
   val edge=if(white)base.copy(.78f)else Color(0xff170d0c)
   drawOval(Color.Black.copy(.46f),Offset(c.x-r*.98f,c.y-r*.54f),Size(r*1.96f,r*1.94f))
   drawOval(edge.copy(.78f),Offset(c.x-r,c.y-r*.78f),Size(r*2f,r*2.02f))
   drawOval(Color.Black.copy(.20f),Offset(c.x-r*.92f,c.y+r*.50f),Size(r*1.84f,r*.26f));drawCircle(Color.White.copy(.18f),r*.96f,c-Offset(0f,r*.15f))
