   drawCircle(Brush.radialGradient(listOf(Color.White.copy(if(white).62f else .38f),base,edge),c-Offset(r*.30f,r*.42f),r*1.30f),r*.89f,c-Offset(0f,r*.10f))
   drawCircle(Color.White.copy(.46f),r*.87f,c-Offset(0f,r*.10f),style=Stroke(r*.065f));drawCircle(Color.Black.copy(.34f),r*.74f,c-Offset(0f,r*.10f),style=Stroke(r*.070f));drawCircle(Color.White.copy(.20f),r*.65f,c-Offset(0f,r*.10f),style=Stroke(r*.035f));val hollow=c-Offset(0f,r*.10f);drawCircle(Brush.radialGradient(listOf(base.copy(.94f),base.copy(.82f),Color.Black.copy(.40f)),hollow-Offset(r*.10f,r*.10f),r*.54f),r*.47f,hollow);drawArc(Color.Black.copy(.38f),190f,160f,false,Offset(hollow.x-r*.48f,hollow.y-r*.48f),Size(r*.96f,r*.96f),style=Stroke(r*.055f));drawArc(Color.White.copy(.18f),10f,160f,false,Offset(hollow.x-r*.45f,hollow.y-r*.45f),Size(r*.90f,r*.90f),style=Stroke(r*.035f));for(g in -2..2){val yy=c.y-r*.10f+g*r*.16f;val span=sqrt(max(0f,r*r*.48f-(yy-(c.y-r*.10f)).pow(2)));drawLine((if(white)Color(0xff80582f)else Color(0xffc08255)).copy(.12f),Offset(c.x-span,yy),Offset(c.x+span,yy+sin(g*1.8f)*r*.05f),r*.025f)}
   drawOval(Color.White.copy(.42f),Offset(c.x-r*.44f,c.y-r*.49f),Size(r*.44f,r*.18f))
   if(available&&!on){drawCircle(Color(0xffb7f45c).copy(.30f+.22f*pulse),r*1.15f,c);drawCircle(Color(0xff9ee84e),r*1.12f,c,style=Stroke(4f))};if(on){drawCircle(Color.Black.copy(.42f),r*1.13f,c,style=Stroke(7f));drawCircle(p.accent,r*1.13f,c,style=Stroke(4f))}
  }
  val active=motion
  for(pt in 0..23){val n=abs(state.position.points[pt]);for(i in 0 until min(n,5)){if(active?.to==pt&&i==min(n,5)-1)continue;piece(center(pt,i),cw*.262f,state.position.points[pt]>0,selected==pt&&i==min(n,5)-1,legal.any{it.from==pt}&&i==min(n,5)-1)};if(n>5)drawCircle(p.accent,cw*.18f,center(pt,4))}
